<?php
namespace App\Http\Controllers;use App\Services\TransportAnalyticsService;use Carbon\Carbon;use Illuminate\Http\Request;
class TransportIndicatorController extends Controller {public function index(Request$r,TransportAnalyticsService$a){$f=$this->filters($r);return view('transport.indicators',['filters'=>$f,'summary'=>$a->summary($r->user()->company_id,$f),'charts'=>$a->charts($r->user()->company_id,$f),'routes'=>$a->byRoute($r->user()->company_id,$f)]);}public static function filters(Request$r):array{$period=$r->input('period','month');$today=today();[$from,$to]=match($period){'today'=>[$today->copy(),$today->copy()],'yesterday'=>[$today->copy()->subDay(),$today->copy()->subDay()],'week'=>[$today->copy()->startOfWeek(),$today->copy()->endOfWeek()],'previous_month'=>[$today->copy()->subMonthNoOverflow()->startOfMonth(),$today->copy()->subMonthNoOverflow()->endOfMonth()],'custom'=>[Carbon::parse($r->input('from',$today)),Carbon::parse($r->input('to',$today))],default=>[$today->copy()->startOfMonth(),$today->copy()->endOfMonth()]};return array_merge(['period'=>$period,'from'=>$from->toDateString(),'to'=>$to->toDateString()],$r->only(['transport_route_id','planned_vehicle_id','planned_driver_id','planned_monitor_id','service_type','shift','status']));}}
